"""Task B bump classifier: TabPFN (GPU), HistGBT (CPU, also the serve-time fallback) and logistic
regression. Plus threshold selection and save/load of a fitted (FeatureBuilder, model) bundle."""
from pathlib import Path

import joblib
import numpy as np
import pandas as pd

from .config import MODELS
from .features import FeatureBuilder


def make_model(name: str):
    if name == "tabpfn":
        from tabpfn import TabPFNClassifier
        return TabPFNClassifier(device="cuda")
    if name == "hgb":
        from sklearn.ensemble import HistGradientBoostingClassifier
        return HistGradientBoostingClassifier(max_iter=400, learning_rate=0.05, random_state=0)
    if name == "logreg":
        from sklearn.linear_model import LogisticRegression
        from sklearn.pipeline import make_pipeline
        from sklearn.preprocessing import StandardScaler
        return make_pipeline(StandardScaler(), LogisticRegression(max_iter=3000))
    raise ValueError(name)


def fit(model_name: str, X: pd.DataFrame, y) -> object:
    clf = make_model(model_name)
    clf.fit(X.fillna(0).values, np.asarray(y).astype(int))
    return clf


def predict_proba(clf, X: pd.DataFrame, batch: int = 5000) -> np.ndarray:
    Xs = X.fillna(0).values
    if len(Xs) == 0:
        return np.zeros(0)
    return np.concatenate([clf.predict_proba(Xs[i:i + batch])[:, 1] for i in range(0, len(Xs), batch)])


def choose_tau(y, p, min_precision: float = 0.5, top_frac: float | None = None) -> float:
    """Lowest threshold whose flagged set has precision >= min_precision (SPEC §9.2).
    Falls back to the top `top_frac` quantile when no threshold reaches the target."""
    y, p = np.asarray(y).astype(int), np.asarray(p)
    order = np.argsort(-p)
    prec = np.cumsum(y[order]) / np.arange(1, len(y) + 1)
    ok = np.where(prec >= min_precision)[0]
    ok = ok[ok >= 9]  # need at least 10 flags for a stable estimate
    if len(ok):
        return float(p[order][ok.max()])
    return float(np.quantile(p, 1 - (top_frac or 0.1)))


class BumpModel:
    """Fitted features + classifier, as used at serve time."""

    def __init__(self, fb: FeatureBuilder, clf, name: str):
        self.fb, self.clf, self.name = fb, clf, name

    def predict(self, df: pd.DataFrame) -> np.ndarray:
        return predict_proba(self.clf, self.fb.transform(df))

    def save(self, path: Path | None = None) -> Path:
        path = Path(path or MODELS / f"bump_{self.name}.joblib")
        path.parent.mkdir(parents=True, exist_ok=True)
        joblib.dump(self, path)
        return path

    @staticmethod
    def load(path: Path | None = None, name: str = "hgb") -> "BumpModel":
        return joblib.load(Path(path or MODELS / f"bump_{name}.joblib"))

"""The single prompt definition for Task A, shared by SFT data (scripts/04), eval (06) and serving."""
import json
import re

from ..cvss import METRICS, VALUES, parse, to_vector

SYSTEM = ("You are an independent CVSS v3.1 analyst, like NIST NVD. Given a CVE description and the "
          "reporter's (CNA's) vector, output the vector an independent analyst would assign, as JSON with "
          "keys AV,AC,PR,UI,S,C,I,A. Change a field only if the description supports it.")
MAX_DESC = 1200
_OBJ = re.compile(r"\{[^{}]*\}")


def prompt(r) -> str:
    """User turn for a row with .cna, .cna_cwe, .cna_vector, .description."""
    desc = r.description[:MAX_DESC]
    return (f"CNA: {r.cna}\nCNA weakness: {r.cna_cwe or 'none'}\nCNA vector: {r.cna_vector}\n"
            f"Description: {desc}")


def messages(r) -> list[dict]:
    return [{"role": "system", "content": SYSTEM}, {"role": "user", "content": prompt(r)}]


def target(r) -> str:
    """Compact JSON of the label vector, e.g. {"AV":"N",...}."""
    return json.dumps({k: parse(r.label_vector)[k] for k in METRICS}, separators=(",", ":"))


def parse_output(text: str | None, fallback: str | None) -> tuple[str | None, bool]:
    """Model text -> (CVSS vector, valid). Takes the first JSON object with all 8 valid fields;
    anything else falls back to `fallback` (the CNA vector) with valid=False."""
    if not isinstance(text, str):
        return fallback, False
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.S)
    for m in _OBJ.finditer(text):
        try:
            j = json.loads(m.group(0))
        except json.JSONDecodeError:
            continue
        if isinstance(j, dict) and all(j.get(k) in VALUES[k] for k in METRICS):
            return to_vector(j), True
    return fallback, False

"""LLM backends for the Task A second opinion. All share predict_vectors(rows) -> list[str] (SPEC §11.7).
Select with PATCHSLOTH_LLM_BACKEND = null | vllm | tinker."""
from typing import Protocol

from .. import config


class LLMBackend(Protocol):
    name: str

    def predict_vectors(self, rows) -> list[str]:
        """rows: objects/Series with cna, cna_cwe, cna_vector, description. Returns CVSS v3.1 vectors."""
        ...


class NullBackend:
    """Returns the CNA vector unchanged (used with --no-llm and in tests)."""
    name = "null"

    def predict_vectors(self, rows) -> list[str]:
        return [r.cna_vector for r in rows]


class VLLMBackend:
    """OpenAI-compatible /v1/chat/completions on the GPU Droplet, model="patchsloth". Filled in at M6."""
    name = "vllm"

    def __init__(self, base_url: str = config.VLLM_BASE_URL, api_key: str = config.VLLM_API_KEY):
        if not base_url:
            raise RuntimeError("VLLM_BASE_URL is not set")
        self.base_url, self.api_key = base_url, api_key

    def predict_vectors(self, rows) -> list[str]:
        raise NotImplementedError("VLLMBackend is implemented with the GPU deployment (M6)")


class TinkerBackend:
    """Tinker sampling client with the saved fine-tuned weights. Filled in at M3."""
    name = "tinker"

    def predict_vectors(self, rows) -> list[str]:
        raise NotImplementedError("TinkerBackend is implemented after the Tinker run (M3)")


def get_backend(name: str | None = None) -> LLMBackend:
    name = (name or config.LLM_BACKEND or "null").lower()
    return {"null": NullBackend, "vllm": VLLMBackend, "tinker": TinkerBackend}[name]()

